-- Generated by build_world_batch.py. See its docstring and each
-- region's notes; style.json holds every claim's sources.

begin;

insert into public.wine_regions
  (region_code, name, aliases, country_code, latitude, longitude, radius_km,
   summary, red_body, red_acidity, red_tannin, pairing, label_note,
   source_url, publication_status)
values
  ('wr_0239', 'Valle del Elqui', '{"Elqui Valley","Elqui","D.O. Valle del Elqui"}'::text[], 'CL', -29.776, -70.617, 74,
   'An arid valley of clear skies, with vineyards cooled by Pacific fog near the coast and others climbing high toward the Andes. Syrah leads the reds and Sauvignon Blanc the whites.',
   null, null, null, null, 'Under Decree 464, wines from the La Serena area may add the term Costa, and wines from the Vicuña and Paiguano areas the term Andes, when at least 85% of the wine comes from areas with that condition.',
   'https://www.winesofchile.org/en/wine-regions', 'published'),
  ('wr_0240', 'Valle del Limarí', '{"Limarí Valley","Limari Valley","Limarí","D.O. Valle del Limarí"}'::text[], 'CL', -30.810, -70.991, 65,
   'A dry valley cooled by Pacific fog in the morning, with pockets of limestone soil. It is best known for fresh, mineral Chardonnay, with Syrah and Pinot Noir also doing well.',
   null, null, null, null, 'Under Decree 464, wines from the Ovalle area may add the term Costa, from Punitaqui the term Entre Cordilleras, and from Monte Patria and Río Hurtado the term Andes, when at least 85% of the wine comes from areas with that condition.',
   'https://www.winesofchile.org/en/wine-regions', 'published'),
  ('wr_0241', 'Valle del Aconcagua', '{"Aconcagua Valley","D.O. Valle del Aconcagua"}'::text[], 'CL', -32.716, -70.721, 47,
   'A valley following the Aconcagua River from the Andes toward the Pacific. Its inland vineyards near the Andes have a long tradition of red wine, led by Cabernet Sauvignon and Carménère, while cooler sites nearer the coast grow white grapes.',
   null, null, null, null, 'Under Decree 464, wines from the Quillota area may add the term Costa; from Hijuelas, Panquehue, Catemu, Llaillay and San Felipe the term Entre Cordilleras; and from Santa María, Calle Larga and San Esteban the term Andes, when at least 85% of the wine comes from areas with that condition.',
   'https://www.winesofchile.org/en/wine-regions', 'published'),
  ('wr_0242', 'Valle de San Antonio', '{"San Antonio Valley","D.O. Valle de San Antonio","Leyda","Valle de Leyda","Leyda Valley"}'::text[], 'CL', -33.639, -71.512, 22,
   'A small, young coastal valley close to the Pacific, with thin, poor soils. Sauvignon Blanc leads, followed by Pinot Noir, Chardonnay and Syrah, and Leyda is its best known zone.',
   null, null, null, null, 'Under Decree 464, wines from the San Juan, Santo Domingo, Cartagena and Algarrobo areas may add the term Costa when at least 85% of the wine comes from areas with that condition.',
   'https://www.winesofchile.org/en/wine-regions', 'published'),
  ('wr_0243', 'Valle del Maule', '{"Maule Valley","Maule","D.O. Valle del Maule"}'::text[], 'CL', -35.767, -71.369, 83,
   'Cabernet Sauvignon leads the plantings in Maule, with País second by area. Old, dry farmed bush vines in the secano of the interior are a noted source of Carignan.',
   null, null, null, null, 'Under Decree 464, País or Cinsault from the dry farmed areas of Talca, Pencahue, San Clemente, San Rafael, San Javier, Villa Alegre, Parral, Linares and Cauquenes may be labelled Secano Interior. Wines from Empedrado and Curepto may add the term Costa, from San Clemente and Colbún the term Andes, and from the other areas Entre Cordilleras.',
   'https://bibliotecadigital.odepa.gob.cl/bitstream/handle/20.500.12650/73137/informe%20catastro%20vit%c3%adcola%202022.xlsx', 'published'),
  ('wr_0244', 'Valle del Itata', '{"Itata Valley","Itata","D.O. Valle del Itata"}'::text[], 'CL', -36.519, -72.334, 45,
   'One of Chile''s oldest wine areas, planted mainly with País and Moscatel de Alejandría, with Cinsault next. Many of its old bush vines grow on granite hillsides and are dry farmed.',
   null, null, null, null, 'Under Decree 464, País or Cinsault from the dry farmed areas of Chillán, Quillón, Portezuelo and Coelemu may be labelled Secano Interior. Wines from Portezuelo and Coelemu may add the term Costa, and from Chillán and Quillón the term Entre Cordilleras.',
   'https://www.winesofchile.org/wine-regions-map/', 'published'),
  ('wr_0245', 'Valle del Biobío', '{"Bío Bío Valley","Bío-Bío Valley","Biobío Valley","Bio Bio Valley","Valle del Bío Bío","D.O. Valle del Bío Bío","Bío Bío"}'::text[], 'CL', -37.550, -72.798, 37,
   'A windy, rainy valley in Chile''s south, where Pinot Noir is the most planted grape, ahead of Chardonnay and País. Riesling and Sauvignon Blanc also suit the area.',
   null, null, null, null, 'Under Decree 464, País or Cinsault from the dry farmed Yumbel area may be labelled Secano Interior. Wines from Yumbel and Mulchén may add the term Entre Cordilleras.',
   'https://www.winesofchile.org/wine-regions-map/', 'published'),
  ('wr_0246', 'Añelo', '{"I.G. Añelo","Anelo","San Patricio del Chañar","Neuquén"}'::text[], 'AR', -38.192, -69.001, 62,
   'Añelo holds almost all of Neuquén''s vineyards, around San Patricio del Chañar, a Patagonian wine zone developed from the late 1990s. Malbec is the main grape, and Pinot Noir and Merlot also do well.',
   null, null, null, null, null,
   'https://www.argentina.gob.ar/sites/default/files/2018/10/neuquen_2023.pdf', 'published'),
  ('wr_0247', 'General Roca', '{"I.G. General Roca"}'::text[], 'AR', -38.371, -67.687, 69,
   'General Roca holds about 70 per cent of Río Negro''s vineyards, in the Alto Valle along the Río Negro. Malbec leads, Merlot and Pinot Noir are also important, and old vineyards give notable Semillon.',
   null, null, null, null, null,
   'https://argentina.gob.ar/sites/default/files/2018/10/anuario_superficie_2024.pdf', 'published'),
  ('wr_0248', 'San Juan', '{"I.G. San Juan"}'::text[], 'AR', -30.508, -68.849, 168,
   'San Juan is Argentina''s second largest wine province. Its warm lowland valleys long supplied everyday wine and grape must, while higher valleys such as Pedernal give fresher wines. Malbec has now overtaken the traditional Syrah.',
   null, null, null, null, null,
   'https://argentina.gob.ar/sites/default/files/2018/10/anuario_superficie_2024.pdf', 'published'),
  ('wr_0249', 'Altos de Pinto Bandeira', '{"DO Altos de Pinto Bandeira"}'::text[], 'BR', -29.098, -51.460, 5,
   'A small appellation for traditional method sparkling wine only, on basalt soils between 520 and 770 metres in Brazil''s Serra Gaúcha. Just three grapes are allowed: Chardonnay, Pinot Noir and Riesling Itálico.',
   null, null, null, null, 'Sparkling wine only, made by the traditional method with a second fermentation in bottle; Charmat is not allowed. Wines spend at least 12 months on the lees before disgorgement, and Reserva needs 24 months in bottle, Gran Reserva 36. Only Chardonnay, Pinot Noir and Riesling Itálico, with Riesling Itálico at most 25% of the blend. Grapes are grown and the wine is made inside the zone.',
   'https://www.decanter.com/wine-news/brazils-altos-de-pinto-bandeira-becomes-first-do-exclusively-for-sparkling-wines-in-the-new-world-496863/', 'published'),
  ('wr_0250', 'Eden Valley', '{}'::text[], 'AU', -34.585, 139.084, 14,
   'A hilly region next to the Barossa Valley, cooler than its neighbour, with rocky, gravelly soils. It is best known for Riesling, while Shiraz is its most planted grape.',
   null, null, null, null, 'A wine labelled with Eden Valley as its only GI must contain at least 85% wine from grapes grown in the Eden Valley GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.australianwine.com/our-places/south-australia/eden-valley-wine-region', 'published'),
  ('wr_0251', 'Mornington Peninsula', '{}'::text[], 'AU', -38.343, 145.066, 16,
   'A peninsula with a cool maritime climate and a mix of sandy, red volcanic and clay based soils. Pinot Noir is the main grape, followed by Chardonnay and Pinot Gris.',
   null, 4, null, null, 'A wine labelled with Mornington Peninsula as its only GI must contain at least 85% wine from grapes grown in the Mornington Peninsula GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.australianwine.com/our-places/victoria/mornington-peninsula-wine-region', 'published'),
  ('wr_0252', 'Heathcote', '{}'::text[], 'AU', -36.748, 144.725, 25,
   'An inland region with warm summers, shaped by the Mount Camel Range, where deep red Cambrian soils give intensely coloured wines. Shiraz is the main grape and its best known wine.',
   4, null, null, null, 'A wine labelled with Heathcote as its only GI must contain at least 85% wine from grapes grown in the Heathcote GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.winecompanion.com.au/wineries/victoria/heathcote', 'published'),
  ('wr_0253', 'Rutherglen', '{}'::text[], 'AU', -36.114, 146.521, 18,
   'An inland region with a continental climate and loamy soils, known for its sweet fortified Muscat and Topaque and for rich reds from Shiraz and Durif.',
   4, null, null, null, 'A wine labelled with Rutherglen as its only GI must contain at least 85% wine from grapes grown in the Rutherglen GI (Wine Australia Regulations 2018, s 26(2)). Topaque, the name that replaced Tokay from 1 September 2020, is a certification trade mark owned by Wine Australia.',
   'https://www.australianwine.com/our-places/victoria/rutherglen-wine-region', 'published'),
  ('wr_0254', 'Beechworth', '{}'::text[], 'AU', -36.363, 146.677, 11,
   'A small, elevated hillside region in north east Victoria with a continental climate and granite based soils. It is best known for Chardonnay, with Pinot Noir, Shiraz and Italian grapes such as Sangiovese also grown.',
   null, null, null, null, 'A wine labelled with Beechworth as its only GI must contain at least 85% wine from grapes grown in the Beechworth GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.australianwine.com/our-places/victoria/beechworth-wine-region', 'published'),
  ('wr_0255', 'Orange', '{}'::text[], 'AU', -33.367, 149.073, 34,
   'A high region around Mount Canobolas, an ancient volcano, on basalt derived soils. By law it covers only land above 600 metres. Chardonnay and Sauvignon Blanc lead the crush, while Shiraz is the most planted grape.',
   null, null, null, null, 'A wine labelled with Orange as its only GI must contain at least 85% wine from grapes grown in the Orange GI (Wine Australia Regulations 2018, s 26(2)). The GI is defined as the contiguous area above 600 metres within the City of Orange and the Shires of Cabonne and Blayney.',
   'https://www.wineaustralia.com/labelling/geographical-indicators/labelling-gi-orange', 'published'),
  ('wr_0256', 'Mudgee', '{}'::text[], 'AU', -32.496, 149.632, 56,
   'An inland region with cold winters, warm dry summers and sandy loam soils over clay, with vineyards dating back to 1858. It is mostly planted to red grapes, led by Shiraz, alongside Chardonnay.',
   null, null, null, null, 'A wine labelled with Mudgee as its only GI must contain at least 85% wine from grapes grown in the Mudgee GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.wineaustralia.com/discover-australian-wine/new-south-wales-wines/mudgee', 'published'),
  ('wr_0257', 'Great Southern', '{}'::text[], 'AU', -34.633, 117.713, 74,
   'A large region in the south of Western Australia, maritime near the coast and more continental inland, with five official subregions. Riesling is its most recognised wine; Shiraz and Cabernet Sauvignon lead the crush.',
   null, null, null, null, 'A wine labelled with Great Southern as its only GI must contain at least 85% wine from grapes grown in the Great Southern GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.wineaustralia.com/discover-australian-wine/western-australia-wines/great-southern', 'published'),
  ('wr_0258', 'Canberra District', '{}'::text[], 'AU', -35.000, 149.047, 53,
   'A region around Canberra, partly in New South Wales and partly in the Australian Capital Territory, with a strongly continental climate. Shiraz, including Shiraz Viognier blends, and Riesling are its best known wines.',
   null, null, null, null, 'A wine labelled with Canberra District as its only GI must contain at least 85% wine from grapes grown in the Canberra District GI (Wine Australia Regulations 2018, s 26(2)).',
   'https://www.wineaustralia.com/labelling/geographical-indicators/labelling-gi-canberra-district', 'published'),
  ('wr_0259', 'Hemel-en-Aarde', '{"Hemel en Aarde"}'::text[], 'ZA', -34.363, 19.257, 5,
   'Three wards in one valley, cooled by ocean breezes and with more rain than most Cape areas. Soils move from clay rich shale near the sea to sandstone and granite inland. Chardonnay and Pinot Noir lead.',
   null, null, null, null, 'Hemel-en-Aarde is not itself a production area: Hemel-en-Aarde Valley, Upper Hemel-en-Aarde Valley and Hemel-en-Aarde Ridge are separate wards of the Walker Bay district, Cape South Coast region (SAWIS, Feb 2026). The first two were defined by Board Notices 88 and 89 of 2006.',
   'https://www.wosa.co.za/The-Industry/Winegrowing-Areas/Winelands-of-South-Africa/', 'published'),
  ('wr_0260', 'Durbanville', '{}'::text[], 'ZA', -33.807, 18.613, 5,
   'A ward of the Cape Town district on rolling hill slopes, cooled by sea breezes and night mists, with deep soils. Sauvignon Blanc is its signature wine, with Cabernet Sauvignon and Merlot among the reds.',
   null, null, null, null, 'A ward (production area) named Durbanville, in the Cape Town district, Coastal Region (SAWIS, Feb 2026); its definition was amended by Board Notices 55 of 2003, 40 of 2005 and 25 of 2007.',
   'https://www.sawis.co.za/cert/download/Production_areas_-_Eng_&_Afr_-_Feb26.pdf', 'published'),
  ('wr_0261', 'Tulbagh', '{}'::text[], 'ZA', -33.264, 19.089, 15,
   'A valley ringed by mountains that are often snow capped in winter. Cold night air is trapped on the valley floor, giving wide swings between day and night. Known for Cap Classique sparkling wine and Shiraz.',
   null, null, null, null, 'Production area (district) Tulbagh, Coastal Region, with no wards (SAWIS, Feb 2026). Defining notice not located.',
   'https://www.wosa.co.za/The-Industry/Winegrowing-Areas/Winelands-of-South-Africa/', 'published'),
  ('wr_0262', 'Robertson', '{}'::text[], 'ZA', -33.869, 19.868, 26,
   'A dry inland valley along the Breede River, which supplies its irrigation, with lime rich soils and warm days cooled by south easterly winds. Best known for Chardonnay and Cap Classique sparkling wine.',
   null, null, null, null, 'Production area (district) Robertson, Breede River Valley region, with fourteen wards (SAWIS, Feb 2026). Defining notice not located.',
   'https://www.wosa.co.za/The-Industry/Winegrowing-Areas/Winelands-of-South-Africa/', 'published'),
  ('wr_0263', 'Cederberg', '{}'::text[], 'ZA', -32.521, 19.303, 7,
   'A remote stand alone ward in the Cederberg mountains, with vineyards at around 1,000 metres, among the highest in South Africa, where frost is a constant risk. Known for Shiraz, Cabernet Sauvignon and Chenin Blanc.',
   null, null, null, null, 'A ward (production area) named Cederberg that belongs to no district or region; SAWIS lists it directly under the Western Cape geographical unit (Feb 2026). Defining notice not located.',
   'https://www.wosa.co.za/The-Industry/Winegrowing-Areas/Winelands-of-South-Africa/', 'published'),
  ('wr_0264', 'Breedekloof', '{}'::text[], 'ZA', -33.654, 19.272, 18,
   'A district of river valleys with soils over beds of river stone and sand, and high rainfall for the Cape. It is a major source of Chenin Blanc, its most planted grape.',
   null, null, null, null, 'Production area (district) Breedekloof, Breede River Valley region, with the wards Goudini and Slanghoek (SAWIS, Feb 2026). Defining notice not located.',
   'https://www.wosa.co.za/The-Industry/Winegrowing-Areas/Winelands-of-South-Africa/', 'published'),
  ('wr_0265', 'Santa Lucia Highlands', '{"SLH"}'::text[], 'US', 36.423, -121.423, 5,
   'Terraces on the east facing slopes of the Santa Lucia Mountains above the Salinas Valley, cooled by fog and strong afternoon winds from Monterey Bay. Pinot Noir and Chardonnay make up most of the vineyard.',
   null, 4, null, null, 'Under federal rules, at least 85% of the wine must come from grapes grown in the AVA named on the label, and the wine must be finished in the state, or one of the states, where the AVA lies.',
   'https://www.santaluciahighlands.com/about/climate', 'published'),
  ('wr_0266', 'Anderson Valley', '{}'::text[], 'US', 39.064, -123.432, 9,
   'A narrow valley in western Mendocino County that opens towards the Pacific along the Navarro River, so sea fog and breezes keep it cool. Pinot Noir dominates, with Chardonnay, sparkling wine and aromatic whites such as Gewürztraminer.',
   null, 4, null, null, 'Under federal rules, at least 85% of the wine must come from grapes grown in the AVA named on the label, and the wine must be finished in the state, or one of the states, where the AVA lies.',
   'https://wineanorak.com/2023/07/03/anderson-valley-california-1-where-the-california-meets-the-pacific-northwest/', 'published'),
  ('wr_0267', 'Lodi', '{}'::text[], 'US', 38.244, -121.240, 27,
   'A large AVA in California''s Central Valley, southeast of Sacramento, where breezes from the Sacramento River Delta temper warm summers. Zinfandel defines it, and it holds more old vines than anywhere else in the country.',
   null, null, null, null, 'Under federal rules, at least 85% of the wine must come from grapes grown in the AVA named on the label, and the wine must be finished in the state, or one of the states, where the AVA lies.',
   'https://www.guildsomm.com/public_content/features/articles/b/stamp/posts/lodi', 'published'),
  ('wr_0268', 'Sierra Foothills', '{}'::text[], 'US', 38.404, -120.699, 59,
   'A long belt of the western Sierra Nevada foothills east of Sacramento, first planted during the Gold Rush. Days are warm and nights cool, and Zinfandel is the main grape.',
   null, null, null, null, 'Under federal rules, at least 85% of the wine must come from grapes grown in the AVA named on the label, and the wine must be finished in the state, or one of the states, where the AVA lies.',
   'https://en.wikipedia.org/wiki/Sierra_Foothills_AVA', 'published'),
  ('wr_0269', 'Monticello', '{"Monticello AVA"}'::text[], 'US', 38.008, -78.598, 35,
   'Rolling country around Charlottesville on the eastern slopes of the Blue Ridge Mountains, where Thomas Jefferson tried to grow vines in the 1770s. Cool air through gaps in the mountains helps lengthen the season.',
   null, null, null, null, 'Under federal rules, at least 85% of the wine must come from grapes grown in the AVA named on the label, and the wine must be finished in the state, or one of the states, where the AVA lies.',
   'https://en.wikipedia.org/wiki/Monticello_AVA', 'published'),
  ('wr_0270', 'Prince Edward County', '{"The County","PEC"}'::text[], 'CA', 44.000, -77.249, 30,
   'Ontario''s most northerly appellation, a near island in Lake Ontario on limestone bedrock. Winters are so cold that vines are buried or covered each autumn. Chardonnay and Pinot Noir lead, and sparkling wine is made too.',
   null, null, null, null, 'A VQA Prince Edward County wine must come at least 85% from grapes grown in the appellation and 100% from Ontario, be made only from vinifera grapes, and be fermented and finished in Ontario.',
   'https://vqaontario.ca/appellations/prince-edward-county/', 'published'),
  ('wr_0271', 'Nova Scotia', '{"Wines of Nova Scotia"}'::text[], 'CA', 45.228, -62.697, 135,
   'Canada''s Atlantic wine province, where vineyards lie close to the sea and the Bay of Fundy tempers a cool climate. It is known for crisp whites such as Tidal Bay and for traditional method sparkling wine.',
   null, null, null, 'Tidal Bay with Atlantic seafood.', 'Wine labelled Nova Scotia Wine must come at least 85% from grapes grown in the province; the Wines of Nova Scotia designation requires 100% Nova Scotia grapes.',
   'https://www.decanter.com/premium/regional-profile-nova-scotia-wines-426262/', 'published'),
  ('wr_0272', 'Yamagata', '{"山形","GI Yamagata"}'::text[], 'JP', 38.443, 140.155, 55,
   'A fruit growing prefecture in northern Honshu with large swings between day and night temperatures. Muscat Bailey A, Delaware and Chardonnay lead, and Takahata town is among Japan''s leading Delaware growers.',
   null, null, null, null, 'A wine labelled GI Yamagata must be made only from listed grape varieties harvested in Yamagata, then produced, stored and bottled in the prefecture, and confirmed by the GI control body.',
   'https://www.nta.go.jp/english/taxes/liquor_administration/02_3.htm', 'published'),
  ('wr_0273', 'Osaka', '{"大阪","GI Osaka"}'::text[], 'JP', 34.659, 135.537, 25,
   'Vineyards on the hills of southern Osaka, around Kashiwara and Habikino, in an area that was once Japan''s largest grape growing district. Much of the wine comes from table grapes such as Delaware.',
   null, null, null, null, 'A wine labelled GI Osaka must be made only from listed grape varieties harvested in Osaka, then produced, stored and bottled in the prefecture, and confirmed by the GI control body.',
   'https://www.nta.go.jp/english/taxes/liquor_administration/02_15.htm', 'published'),
  ('wr_0274', 'Nashik', '{"Nashik Valley","Nashik Valley Wine","Nasik"}'::text[], 'IN', 19.997, 73.791, 30,
   'India''s main wine region, northeast of Mumbai, with vineyards at about 600 to 700 metres. Pruning is timed so grapes ripen in the dry, cooler winter, with warm days and cool nights, and harvest falls early in the year.',
   null, null, null, null, 'Nashik Valley Wine must come at least 80% from grapes grown in Nashik district and be made and bottled there by a winery based in the region.',
   'https://search.ipindia.gov.in/GIRPublicSearch/Application/Details/123', 'published'),
  ('wr_0275', 'Yantai', '{"烟台","Yantai Wine","烟台葡萄酒"}'::text[], 'CN', 37.217, 120.815, 30,
   'A coastal region on the Shandong Peninsula with a maritime climate, mild enough that vines need not be buried in winter. Modern Chinese winemaking began here when Changyu was founded in 1892.',
   null, null, null, null, 'Yantai Wine, a protected geographical indication, must be made from at least 85% grapes grown in Yantai, with growing and winemaking inside the Yantai administrative area.',
   'https://ec.europa.eu/geographical-indications-register/eambrosia-public-api/api/v1/attachments/65627', 'published');

insert into public.grapes
  (grape_code, name, aliases, colour, summary, tastes, aged_note,
   body, acidity, tannin, publication_status)
values
  ('gr_0178', 'Bonarda', '{"Bonarda Argentina","Bonarda de Argentina","Douce Noir","Douce Noire","Corbeau","Corbeau Noir","Charbono"}'::text[], 'red',
   'Argentina''s second most planted red grape, identical to Douce Noir (Corbeau) from Savoie and California''s Charbono, and not Italian Bonarda. It gives fruity, soft reds of moderate alcohol.',
   '{"Spice"}'::text[], null, null, null, null, 'published'),
  ('gr_0179', 'País', '{"Listán Prieto","Mission","Criolla Chica"}'::text[], 'red',
   'A red grape the Spanish brought to the Americas, the same variety as Listán Prieto and Mission. Old vines in Chile''s south now give pale, light reds.',
   '{"Raspberry","Red cherry"}'::text[], null, 2, null, null, 'published'),
  ('gr_0180', 'Durif', '{"Petite Sirah"}'::text[], 'red',
   'A dark red grape bred in France in the late 19th century, with Syrah as one parent. Known as Petite Sirah in California, it gives full bodied, tannic wines.',
   '{"Dark chocolate","Blackberry","Spice"}'::text[], 'Can age for around ten years.', 5, 3, 4, 'published'),
  ('gr_0181', 'Muscat à Petits Grains Rouges', '{"Muscat à Petits Grains Rouge","Brown Muscat","Rutherglen Brown Muscat","Muscat Rouge à Petits Grains","Brown Frontignac"}'::text[], 'red',
   'The dark skinned form of Muscat Blanc à Petits Grains, catalogued as a colour mutation. In Rutherglen it is the only grape used for Rutherglen Muscat, a sweet fortified wine.',
   '{"Raisin","Chocolate"}'::text[], 'Rutherglen Muscat is aged in barrel and graded by age as Rutherglen, Classic, Grand and Rare.', null, null, null, 'published'),
  ('gr_0182', 'Colombard', '{"Colombar","French Colombard"}'::text[], 'white',
   'A white grape from Gascony in south west France, long grown there for brandy. It gives light, crisp wines with high acidity and is widely planted in South Africa.',
   '{"Honeydew melon","White peach","Citrus"}'::text[], null, 2, 4, null, 'published'),
  ('gr_0183', 'Viognier', '{}'::text[], 'white',
   'A white grape from the northern Rhône, where it makes Condrieu. It gives full bodied, perfumed wines with fairly low acidity.',
   '{"Apricot","Peach","Honeysuckle","Rose"}'::text[], 'Usually best drunk young.', 5, 2, null, 'published'),
  ('gr_0184', 'Barbera', '{}'::text[], 'red',
   'A red grape from Piedmont in northern Italy, long one of Italy''s most planted reds. It gives deeply coloured wines with high acidity and low tannin.',
   '{"Cherry","Dried herbs"}'::text[], null, null, 4, 2, 'published'),
  ('gr_0185', 'Delaware', '{}'::text[], 'white',
   'An American grape with pinkish red skins, grown for eating and for wine. A major table grape in Japan, it is the main white wine grape of Yamagata and Osaka.',
   '{}'::text[], null, null, null, null, 'published'),
